/*
cot, acos from trigonometry
C_f = 1/2 [cot(acos((q_f²+r_f²-p_f²)/(2 q_f r_f))), cot(acos((r_f²+p_f²-q_f²)/(2 r_f p_f))), cot(acos((p_f²+q_f²-r_f²)/(2 p_f q_f)))]

where

p_i ∈ ℝ
q_i ∈ ℝ
r_i ∈ ℝ

*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>
#include "type_helper.h"

using namespace iheartmesh;
struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    std::vector<Eigen::Matrix<DT, 1, 3>> C;

    heartlib(
        const std::vector<double> & p,
        const std::vector<double> & q,
        const std::vector<double> & r)
    {
        const long dim_0 = p.size();
        assert( q.size() == dim_0 );
        assert( r.size() == dim_0 );
        // C_f = 1/2 [cot(acos((q_f²+r_f²-p_f²)/(2 q_f r_f))), cot(acos((r_f²+p_f²-q_f²)/(2 r_f p_f))), cot(acos((p_f²+q_f²-r_f²)/(2 p_f q_f)))]
        C.resize(dim_0);
        for( int f=1; f<=dim_0; f++){
            Eigen::Matrix<DT, 1, 3> C_f_0;
            C_f_0 << 1/tan(acos((pow(q.at(f-1), 2) + pow(r.at(f-1), 2) - pow(p.at(f-1), 2)) / DT((2 * q.at(f-1) * r.at(f-1))))), 1/tan(acos((pow(r.at(f-1), 2) + pow(p.at(f-1), 2) - pow(q.at(f-1), 2)) / DT((2 * r.at(f-1) * p.at(f-1))))), 1/tan(acos((pow(p.at(f-1), 2) + pow(q.at(f-1), 2) - pow(r.at(f-1), 2)) / DT((2 * p.at(f-1) * q.at(f-1)))));
            C.at(f-1) = 1 / DT(2) * C_f_0;
        }
    }
};

