function output = heartlib(p, q, r)
% output = heartlib(p, q, r)
%
%    cot, acos from trigonometry
%    C_f = 1/2 [cot(acos((q_f²+r_f²-p_f²)/(2 q_f r_f))), cot(acos((r_f²+p_f²-q_f²)/(2 r_f p_f))), cot(acos((p_f²+q_f²-r_f²)/(2 p_f q_f)))]
%    
%    where
%    
%    p_i ∈ ℝ
%    q_i ∈ ℝ
%    r_i ∈ ℝ
%    
    p = reshape(p,[],1);
    q = reshape(q,[],1);
    r = reshape(r,[],1);

    dim_0 = size(p, 1);
    assert( size(p,1) == dim_0 );
    assert( size(q,1) == dim_0 );
    assert( size(r,1) == dim_0 );

    % C_f = 1/2 [cot(acos((q_f²+r_f²-p_f²)/(2 q_f r_f))), cot(acos((r_f²+p_f²-q_f²)/(2 r_f p_f))), cot(acos((p_f²+q_f²-r_f²)/(2 p_f q_f)))]

    C = zeros(dim_0, 1, 3);
    for f = 1:dim_0
        C_f_0 = zeros(1, 3);
        C_f_0(1,:) = [1./tan(acos((q(f).^2 + r(f).^2 - p(f).^2) / (2 * q(f) * r(f)))), 1./tan(acos((r(f).^2 + p(f).^2 - q(f).^2) / (2 * r(f) * p(f)))), 1./tan(acos((p(f).^2 + q(f).^2 - r(f).^2) / (2 * p(f) * q(f))))];
        squeeze(C(f,:,:)) = 1 / 2 * C_f_0;
    end
    output.C = C;
end

